import { randomUUID } from 'node:crypto'
import JSZip from 'jszip'
import type { Principal } from '../domain/access-control.js'
import type { DatabaseState } from '../domain/types.js'
import type {
  CreateTestDesignInput, CoverageAudit, HistoricalCaseSnapshot, ImpactedRegressionReference, RetrievalSnapshot, SmokeCandidateRelation, TestCase,
  TestCaseContent, TestCaseSetVersion, TestDataRequirement, TestDataRequirementSetVersion, TestDesign, TestDesignBasisSnapshot,
  TestDesignNodeKey, TestDesignState, TestDesignWorkflowRun, TestExecutionHandoff, TestPointNodeRevision,
  TestPointTreeOperation, TestPointTreeRevision, WorkflowArtifact, WorkflowNodeRun,
} from '../domain/test-design-types.js'
import type { StateStore } from '../infrastructure/store.js'
import { canonicalJson, canonicalSha256 } from './canonical-json.js'
import { auditTestDesignCoverage } from './test-design-coverage-auditor.js'
import { assertEtag, etag, TestDesignError, validateCaseDependencyGraph, validateCreateTestDesignInput, validateDesignCandidateNodes, validateTestCaseContent, validateTreeNodes } from './test-design-validation.js'

export interface TestDesignAgentRuntime {
  readiness?(): Promise<{ ready: boolean; agents: Array<{ agentKey: string; ready: boolean; reason?: string }> }>
  execute(input: {
    stage: 'test_analysis' | 'functional_design' | 'non_functional_design' | 'test_case_synthesis'
    run: TestDesignWorkflowRun
    upstream: unknown
  }, signal: AbortSignal): Promise<{ schemaVersion: string; content: unknown; execution?: WorkflowNodeRun['execution'] }>
}
export interface TestCaseAssetProjector { ingest(input: { knowledgeBaseId: string; sourceType: 'upload'; sourceKey: string; assetType: string; displayName: string; logicalPath: string; content: string; taskTrigger?: 'upload' | 'retry' }): Promise<{ version: { id: string }; task: unknown }> }

type SynthesisResult = { cases: TestCaseContent[]; dataRequirements: Array<Omit<TestDataRequirement, 'id' | 'caseIds' | 'testPointIds'> & { ref: string; caseIndexes: number[]; testPointIds: string[] }> }

export class TestDesignService {
  private readonly activeRuns = new Map<string, AbortController>()
  constructor(private readonly store: StateStore, private readonly runtime?: TestDesignAgentRuntime, private readonly projector?: TestCaseAssetProjector) {}

  async inputCandidates(projectVersionId: string) {
    const state = await this.store.snapshot()
    const projectVersion = required(state.projectVersions.find(item => item.id === projectVersionId), 'PROJECT_VERSION_NOT_FOUND', '项目版本不存在')
    const projectBases = state.knowledgeBases.filter(item => item.projectId === projectVersion.projectId)
    const reviewBaselines = state.technicalSolutionRuns.filter(run => run.projectVersionId === projectVersionId && run.status === 'succeeded' && run.result).flatMap(technicalRun => {
      const reviewRun = state.reviewRuns.find(run => run.id === technicalRun.sourceReviewRunId && run.projectVersionId === projectVersionId && run.status === 'succeeded' && run.result)
      const technicalReview = state.technicalSolutionReviews.find(item => item.id === technicalRun.technicalReviewId)
      return reviewRun ? [{ sourceReviewRunId: reviewRun.id, sourceTechnicalSolutionRunId: technicalRun.id, requirementDocumentTitle: reviewRun.documentTitle, technicalReviewName: technicalReview?.name ?? '技术方案评审', reviewCompletedAt: reviewRun.finishedAt ?? reviewRun.createdAt, technicalCompletedAt: technicalRun.finishedAt ?? technicalRun.createdAt, label: `${reviewRun.documentTitle} / ${technicalReview?.name ?? technicalRun.id} / ${technicalRun.id.slice(-8)}`, selectable: true }] : []
    })
    const knowledgeAssets = projectBases.flatMap(base => state.assets.filter(asset => asset.knowledgeBaseId === base.id).flatMap(asset => state.versions.filter(version => version.assetId === asset.id).map(version => ({ assetId: asset.id, assetVersionId: version.id, version: version.number, contentHash: version.contentHash, displayName: asset.displayName, logicalPath: asset.logicalPath, assetType: asset.assetType, status: version.status, selectable: version.status === 'ready', reason: version.status === 'ready' ? undefined : '资产版本未就绪' }))))
    const designState = readDesignState(state)
    const agentReadiness = this.runtime?.readiness ? await this.runtime.readiness() : { ready: Boolean(this.runtime), agents: ['test-analysis', 'functional-test-design', 'non-functional-test-design', 'test-case-synthesis'].map(agentKey => ({ agentKey, ready: Boolean(this.runtime), reason: this.runtime ? undefined : '测试设计 Agent Runtime 未配置' })) }
    return {
      projectVersion: { id: projectVersion.id, projectId: projectVersion.projectId, name: projectVersion.name, status: projectVersion.status },
      reviewBaselines,
      knowledgeAssets,
      fixedIndexes: projectBases.flatMap(base => state.indexes.filter(index => index.knowledgeBaseId === base.id && index.status === 'active').map(index => ({ id: index.id, selectable: true }))),
      historicalCaseSets: designState.caseSetVersions.filter(item => item.projectId === projectVersion.projectId).map(item => ({ id: item.id, name: item.name, version: item.version, memberCount: item.members.length, contentSha256: item.contentSha256 })),
      historicalCaseAssets: knowledgeAssets.filter(item => item.assetType === 'test_case' && item.selectable),
      agentReadiness,
    }
  }

  async createDesign(projectVersionId: string, rawInput: unknown, principal: Principal) {
    const input = validateCreateTestDesignInput(rawInput)
    return this.store.transaction(state => {
      const projectVersion = required(state.projectVersions.find(item => item.id === projectVersionId), 'PROJECT_VERSION_NOT_FOUND', '项目版本不存在')
      if (projectVersion.status !== 'open') throw new TestDesignError('PROJECT_VERSION_READ_ONLY', '当前项目版本只读', 409)
      validateDesignSources(state, projectVersion.projectId, projectVersionId, input)
      const design: TestDesign = { id: `test_design_${randomUUID()}`, projectVersionId, projectId: projectVersion.projectId, name: input.name, objective: input.objective, basisMode: input.basisMode, input, logicalInputSha256: canonicalSha256(input), createdBy: principal.subjectId, createdAt: now() }
      designState(state).designs.push(design)
      return structuredClone(design)
    })
  }

  async listDesigns(projectVersionId: string, filters: { basisMode?: string } = {}) {
    const state = await this.store.snapshot(); const aggregate = readDesignState(state)
    return aggregate.designs.filter(item => item.projectVersionId === projectVersionId && (!filters.basisMode || item.basisMode === filters.basisMode)).sort(newest).map(design => ({ ...design, latestRun: aggregate.runs.filter(run => run.testDesignId === design.id).sort(newest)[0] ?? null }))
  }

  async getDesign(projectVersionId: string, designId: string) {
    const state = await this.store.snapshot(); return structuredClone(findDesign(state, projectVersionId, designId))
  }

  async createRun(projectVersionId: string, designId: string, idempotencyKey: string, principal: Principal) {
    if (!idempotencyKey?.trim()) throw new TestDesignError('IDEMPOTENCY_KEY_REQUIRED', '创建运行必须提供 Idempotency-Key', 400)
    const readiness = this.runtime?.readiness ? await this.runtime.readiness() : { ready: Boolean(this.runtime) }
    if (!readiness.ready) throw new TestDesignError('TEST_DESIGN_AGENT_NOT_READY', '四个测试设计 Agent 尚未全部发布或通过模型门禁', 409, readiness)
    const created = await this.store.transaction(state => {
      const design = findDesign(state, projectVersionId, designId)
      const projectVersion = required(state.projectVersions.find(item => item.id === projectVersionId), 'PROJECT_VERSION_NOT_FOUND', '项目版本不存在')
      if (projectVersion.status !== 'open') throw new TestDesignError('PROJECT_VERSION_READ_ONLY', '当前项目版本只读', 409)
      const aggregate = designState(state)
      const existing = aggregate.runs.find(run => run.testDesignId === designId && run.idempotencyKey === idempotencyKey)
      if (existing) return { run: structuredClone(existing), created: false }
      if (!this.runtime) throw new TestDesignError('TEST_DESIGN_AGENT_NOT_READY', '四个测试设计 Agent 尚未完成运行时配置', 409)
      const runId = `test_design_run_${randomUUID()}`
      const createdAt = now()
      const run: TestDesignWorkflowRun = {
        id: runId, testDesignId: design.id, projectVersionId, status: 'queued', stage: 'test_analysis', progress: 0, idempotencyKey,
        basisSnapshot: buildBasisSnapshot(state, design, createdAt), retrievalSnapshot: buildRetrievalSnapshot(state, design, createdAt), historicalSnapshot: buildHistoricalSnapshot(state, design, createdAt),
        nodeRuns: workflowNodes(runId), artifacts: [], gateDecisions: [], testCases: [], dataSetVersions: [], coverageAudits: [], smokeCandidates: [], impactedRegression: [], findings: [], confirmationItems: [], events: [], createdBy: principal.subjectId, createdAt,
      }
      aggregate.runs.push(run)
      return { run: structuredClone(run), created: true }
    })
    if (created.run.status === 'queued') await this.schedule(created.run.id)
    return created.run
  }

  async listRuns(projectVersionId: string, designId: string) {
    const state = await this.store.snapshot(); findDesign(state, projectVersionId, designId)
    return readDesignState(state).runs.filter(item => item.testDesignId === designId).sort(newest).map(run => presentRun(run))
  }

  async getRun(projectVersionId: string, designId: string, runId: string) {
    const state = await this.store.snapshot(); return presentRun(findRun(state, projectVersionId, designId, runId), true)
  }

  async processPreparedRun(runId: string, signal = new AbortController().signal) {
    if (!this.runtime) throw new TestDesignError('TEST_DESIGN_AGENT_NOT_READY', '测试设计 Agent Runtime 未配置', 409)
    const run = await this.loadRun(runId)
    if (run.status === 'cancelled' || run.status === 'succeeded') return run
    try {
      if (['pending', 'queued', 'running', 'failed'].includes(node(run, 'test_analysis').status)) {
        const output = await this.executeNode(runId, 'test_analysis', signal, { basisSnapshot: run.basisSnapshot, retrievalSnapshot: run.retrievalSnapshot, historicalSnapshot: run.historicalSnapshot })
        await this.store.transaction(state => {
          const current = findRunById(state, runId); publishArtifact(current, 'test_analysis', output); materializeAnalysisIssues(current, output.content); finishNode(current, 'test_analysis', output.execution); startGate(current, 'scope_gate', output)
          Object.assign(current, { status: 'waiting_gate', stage: 'scope_gate', progress: 20 })
        })
        return this.loadRun(runId)
      }
      const refreshed = await this.loadRun(runId)
      if (!latestApprovedGate(refreshed, 'scope')) return refreshed
      if (node(refreshed, 'functional_design').status !== 'succeeded' || node(refreshed, 'non_functional_design').status !== 'succeeded') {
        const analysis = artifact(refreshed, 'test_analysis').content
        const runFunctional = node(refreshed, 'functional_design').status !== 'succeeded'
        const runNonFunctional = node(refreshed, 'non_functional_design').status !== 'succeeded'
        const [functionalResult, nonFunctionalResult] = await Promise.allSettled([
          runFunctional ? this.executeNode(runId, 'functional_design', signal, analysis) : Promise.resolve({ schemaVersion: artifact(refreshed, 'functional_design').schemaVersion, content: artifact(refreshed, 'functional_design').content, execution: undefined }),
          runNonFunctional ? this.executeNode(runId, 'non_functional_design', signal, analysis) : Promise.resolve({ schemaVersion: artifact(refreshed, 'non_functional_design').schemaVersion, content: artifact(refreshed, 'non_functional_design').content, execution: undefined }),
        ])
        await this.store.transaction(state => {
          const current = findRunById(state, runId)
          if (runFunctional && functionalResult.status === 'fulfilled') { publishArtifact(current, 'functional_design', functionalResult.value); finishNode(current, 'functional_design', functionalResult.value.execution) }
          else if (runFunctional && functionalResult.status === 'rejected') failNode(current, 'functional_design', functionalResult.reason)
          if (runNonFunctional && nonFunctionalResult.status === 'fulfilled') { publishArtifact(current, 'non_functional_design', nonFunctionalResult.value); finishNode(current, 'non_functional_design', nonFunctionalResult.value.execution) }
          else if (runNonFunctional && nonFunctionalResult.status === 'rejected') failNode(current, 'non_functional_design', nonFunctionalResult.reason)
          if (functionalResult.status === 'rejected' || nonFunctionalResult.status === 'rejected') return
          mergeTree(current, functionalResult.value.content, nonFunctionalResult.value.content, current.createdBy)
          finishNode(current, 'tree_merge'); startGate(current, 'tree_gate', current.testPointTree)
          Object.assign(current, { status: 'waiting_gate', stage: 'tree_gate', progress: 55 })
        })
        if (functionalResult.status === 'rejected') throw functionalResult.reason
        if (nonFunctionalResult.status === 'rejected') throw nonFunctionalResult.reason
        return this.loadRun(runId)
      }
      const afterDesign = await this.loadRun(runId)
      if (!latestApprovedGate(afterDesign, 'test-point-tree')) return afterDesign
      if (node(afterDesign, 'test_case_synthesis').status !== 'succeeded') {
        const tree = required(afterDesign.testPointTree, 'TEST_POINT_TREE_APPROVAL_REQUIRED', '测试点树不存在')
        const treeVersion = required(tree.versions.find(item => item.id === tree.currentApprovedVersionId), 'TEST_POINT_TREE_APPROVAL_REQUIRED', '测试点树未批准')
        const output = await this.executeNode(runId, 'test_case_synthesis', signal, { treeVersion, treeRevision: tree.revisions.find(item => item.revision === treeVersion.revision) })
        await this.store.transaction(state => {
          const current = findRunById(state, runId); publishArtifact(current, 'test_case_synthesis', output); finishNode(current, 'test_case_synthesis', output.execution)
          materializeSynthesis(current, output.content, current.createdBy)
          const audit = runCoverageAudit(current); current.coverageAudits.forEach(item => { item.status = 'stale' }); current.coverageAudits.push(audit); finishNode(current, 'coverage_audit')
          Object.assign(current, { status: 'succeeded', stage: 'completed', progress: 100, finishedAt: now() })
        })
      }
      return this.loadRun(runId)
    } catch (error) {
      await this.store.transaction(state => {
        const current = readDesignState(state).runs.find(item => item.id === runId); if (!current || current.status === 'cancelled') return
        const message = error instanceof Error ? error.message : String(error); const active = current.nodeRuns.find(item => item.status === 'running'); const execution = error && typeof error === 'object' && 'execution' in error ? (error as { execution?: WorkflowNodeRun['execution'] }).execution : undefined; if (active) Object.assign(active, { status: 'failed', finishedAt: now(), error: message, errorCode: errorCode(message), ...(execution ? { execution } : {}) })
        Object.assign(current, { status: 'failed', stage: 'failed', finishedAt: now(), error: message, errorCode: errorCode(message) })
      }).catch(() => undefined)
      throw error
    }
  }

  async applyGateDecision(projectVersionId: string, designId: string, runId: string, gateKey: 'scope' | 'test-point-tree', input: { targetId: string; targetRevision: number; decision: 'approved' | 'rejected'; comment?: string; expectedVersion: number }, principal: Principal) {
    const shouldResume = await this.store.transaction(state => {
      const run = findRun(state, projectVersionId, designId, runId); const gateNode = node(run, gateKey === 'scope' ? 'scope_gate' : 'tree_gate')
      if (gateNode.status !== 'waiting_gate') throw new TestDesignError('WORKFLOW_GATE_VERSION_CONFLICT', '当前门禁不在等待决策状态', 409)
      const decisions = run.gateDecisions.filter(item => item.gateKey === gateKey)
      if (decisions.length !== input.expectedVersion) throw new TestDesignError('WORKFLOW_GATE_VERSION_CONFLICT', '门禁版本已变化', 409)
      const expectedTarget = gateKey === 'scope' ? artifact(run, 'test_analysis').id : required(run.testPointTree?.id, 'TEST_POINT_TREE_APPROVAL_REQUIRED', '测试点树不存在')
      const expectedRevision = gateKey === 'scope' ? artifact(run, 'test_analysis').generation : run.testPointTree!.currentRevision
      if (input.targetId !== expectedTarget || input.targetRevision !== expectedRevision) throw new TestDesignError('WORKFLOW_GATE_VERSION_CONFLICT', '门禁目标已变化', 409)
      run.gateDecisions.push({ id: `gate_decision_${randomUUID()}`, gateKey, targetId: input.targetId, targetRevision: input.targetRevision, version: decisions.length + 1, decision: input.decision, ...(input.comment?.trim() ? { comment: input.comment.trim().slice(0, 4_000) } : {}), actorId: principal.subjectId, createdAt: now() })
      Object.assign(gateNode, { status: input.decision === 'approved' ? 'succeeded' : 'failed', finishedAt: now() })
      if (input.decision === 'rejected') { Object.assign(run, { status: 'failed', stage: 'failed', errorCode: 'WORKFLOW_GATE_REJECTED', error: '人工门禁已拒绝', finishedAt: now() }); return false }
      if (gateKey === 'scope') { queueNode(run, 'functional_design'); queueNode(run, 'non_functional_design'); Object.assign(run, { status: 'queued', stage: 'functional_design', progress: 25 }) }
      else { approveCurrentTree(run, principal.subjectId); queueNode(run, 'test_case_synthesis'); Object.assign(run, { status: 'queued', stage: 'test_case_synthesis', progress: 60 }) }
      return true
    })
    if (shouldResume) await this.schedule(runId)
    return this.getRun(projectVersionId, designId, runId)
  }

  async cancelRun(projectVersionId: string, designId: string, runId: string, principal: Principal) {
    const controller = this.activeRuns.get(runId); controller?.abort(new Error(`WORKFLOW_CANCELLED: ${principal.subjectId}`))
    await this.store.cancelTestDesignJob?.(runId)
    return this.store.transaction(state => { const run = findRun(state, projectVersionId, designId, runId); if (run.status === 'succeeded') throw new TestDesignError('WORKFLOW_NODE_NOT_RETRYABLE', '已完成运行不能取消', 409); Object.assign(run, { status: 'cancelled', stage: 'cancelled', finishedAt: now(), errorCode: 'WORKFLOW_CANCELLED', error: '运行已由用户取消' }); run.nodeRuns.filter(item => ['pending', 'queued', 'running', 'waiting_gate'].includes(item.status)).forEach(item => { item.status = 'cancelled'; item.finishedAt = now() }); return presentRun(run, true) })
  }

  async fullRerun(projectVersionId: string, designId: string, runId: string, idempotencyKey: string, principal: Principal) { await this.getRun(projectVersionId, designId, runId); return this.createRun(projectVersionId, designId, idempotencyKey, principal) }

  async retryDesignNode(projectVersionId: string, designId: string, runId: string, nodeKey: 'functional_design' | 'non_functional_design') {
    await this.store.transaction(state => { const run = findRun(state, projectVersionId, designId, runId); const target = node(run, nodeKey); if (target.status !== 'failed') throw new TestDesignError('WORKFLOW_NODE_NOT_RETRYABLE', '只有失败的设计节点可以单独重试', 409); target.generation += 1; target.status = 'queued'; target.error = undefined; target.errorCode = undefined; node(run, 'tree_merge').status = 'pending'; node(run, 'tree_gate').status = 'pending'; Object.assign(run, { status: 'queued', stage: nodeKey, error: undefined, errorCode: undefined, finishedAt: undefined }) }); await this.schedule(runId); return this.getRun(projectVersionId, designId, runId)
  }

  async reviseScope(projectVersionId: string, designId: string, runId: string) {
    await this.store.transaction(state => { const run = findRun(state, projectVersionId, designId, runId); const target = node(run, 'test_analysis'); target.generation += 1; target.status = 'queued'; target.error = undefined; target.errorCode = undefined; for (const downstream of run.nodeRuns.filter(item => item.nodeKey !== 'test_analysis')) { downstream.generation += 1; downstream.status = 'pending'; downstream.outputArtifactId = undefined; downstream.error = undefined; downstream.errorCode = undefined } run.testPointTree = undefined; run.testCases = []; run.dataSetVersions = []; invalidateAudit(run); Object.assign(run, { status: 'queued', stage: 'test_analysis', progress: 0, error: undefined, errorCode: undefined, finishedAt: undefined }) }); await this.schedule(runId); return this.getRun(projectVersionId, designId, runId)
  }

  async resynthesize(projectVersionId: string, designId: string, runId: string) {
    await this.store.transaction(state => { const run = findRun(state, projectVersionId, designId, runId); approvedTreeVersion(run); const target = node(run, 'test_case_synthesis'); target.generation += 1; target.status = 'queued'; target.error = undefined; target.errorCode = undefined; node(run, 'coverage_audit').status = 'pending'; run.testCases = []; run.dataSetVersions = []; invalidateAudit(run); Object.assign(run, { status: 'queued', stage: 'test_case_synthesis', progress: 60, error: undefined, errorCode: undefined, finishedAt: undefined }) }); await this.schedule(runId); return this.getRun(projectVersionId, designId, runId)
  }

  async getTree(projectVersionId: string, designId: string, runId: string) {
    const run = await this.loadScopedRun(projectVersionId, designId, runId); const tree = required(run.testPointTree, 'TEST_POINT_TREE_NOT_FOUND', '测试点树尚未生成')
    const revision = tree.revisions.find(item => item.revision === tree.currentRevision)!; return { tree: structuredClone(tree), revision: structuredClone(revision), etag: etag('tree', tree.id, revision.revision, revision.treeSha256) }
  }
  async treeRevisions(projectVersionId: string, designId: string, runId: string) { const run = await this.loadScopedRun(projectVersionId, designId, runId); return structuredClone(required(run.testPointTree, 'TEST_POINT_TREE_NOT_FOUND', '测试点树尚未生成').revisions) }
  async treeDiff(projectVersionId: string, designId: string, runId: string, from: number, to: number) { const run = await this.loadScopedRun(projectVersionId, designId, runId); const tree = required(run.testPointTree, 'TEST_POINT_TREE_NOT_FOUND', '测试点树尚未生成'); const left = required(tree.revisions.find(item => item.revision === from), 'TEST_POINT_TREE_REVISION_NOT_FOUND', '起始树 revision 不存在'); const right = required(tree.revisions.find(item => item.revision === to), 'TEST_POINT_TREE_REVISION_NOT_FOUND', '目标树 revision 不存在'); return structuralDiff(left.nodes, right.nodes) }

  async patchTree(projectVersionId: string, designId: string, runId: string, ifMatch: string | undefined, input: { operations: TestPointTreeOperation[]; reason: string }, principal: Principal) {
    return this.store.transaction(state => {
      assertOpenVersion(state, projectVersionId); const run = findRun(state, projectVersionId, designId, runId); const tree = required(run.testPointTree, 'TEST_POINT_TREE_NOT_FOUND', '测试点树尚未生成'); const current = tree.revisions.find(item => item.revision === tree.currentRevision)!
      assertEtag(ifMatch, etag('tree', tree.id, current.revision, current.treeSha256), 'TEST_POINT_TREE_REVISION_CONFLICT')
      if (!Array.isArray(input.operations) || !input.operations.length || input.operations.length > 100) throw new TestDesignError('TEST_POINT_TREE_OPERATION_INVALID', 'operations 必须包含 1 到 100 个操作', 422)
      const nodes = applyTreeOperations(current.nodes, input.operations)
      const revision: TestPointTreeRevision = { revision: current.revision + 1, parentRevision: current.revision, nodes, operations: structuredClone(input.operations), reason: cleanRequired(input.reason, '修改说明', 2_000), actorId: principal.subjectId, treeSha256: validateTreeNodes(nodes), createdAt: now() }
      tree.revisions.push(revision); tree.currentRevision = revision.revision; tree.currentApprovedVersionId = undefined
      run.testCases.forEach(testCase => { if (!testCase.tombstonedAt) testCase.reviewState = 'draft' }); run.coverageAudits.forEach(audit => { audit.status = 'stale' }); node(run, 'tree_gate').status = 'waiting_gate'; Object.assign(run, { status: 'waiting_gate', stage: 'tree_gate', progress: 55 })
      return { tree: structuredClone(tree), revision: structuredClone(revision), etag: etag('tree', tree.id, revision.revision, revision.treeSha256) }
    })
  }

  async approveTree(projectVersionId: string, designId: string, runId: string, ifMatch: string | undefined, principal: Principal) {
    return this.store.transaction(state => { assertOpenVersion(state, projectVersionId); const run = findRun(state, projectVersionId, designId, runId); const tree = required(run.testPointTree, 'TEST_POINT_TREE_NOT_FOUND', '测试点树尚未生成'); const revision = tree.revisions.find(item => item.revision === tree.currentRevision)!; assertEtag(ifMatch, etag('tree', tree.id, revision.revision, revision.treeSha256), 'TEST_POINT_TREE_REVISION_CONFLICT'); const version = approveCurrentTree(run, principal.subjectId); return structuredClone(version) })
  }

  async listCases(projectVersionId: string, designId: string, runId: string, filters: { dimension?: string; executionMethod?: string; status?: string } = {}) {
    const run = await this.loadScopedRun(projectVersionId, designId, runId)
    return run.testCases.filter(item => !item.tombstonedAt).filter(item => { const content = currentCaseRevision(item).content; return (!filters.dimension || content.dimension === filters.dimension) && (!filters.executionMethod || content.executionMethods.some(method => method.method === filters.executionMethod)) && (!filters.status || item.reviewState === filters.status) }).map(testCase => presentCase(testCase))
  }

  async createCase(projectVersionId: string, designId: string, runId: string, rawContent: unknown, principal: Principal) {
    return this.store.transaction(state => { assertOpenVersion(state, projectVersionId); const run = findRun(state, projectVersionId, designId, runId); const treeVersion = approvedTreeVersion(run); const points = approvedPointIds(run, treeVersion.id); const content = validateTestCaseContent(rawContent, points); const testCase = newCase(run.id, treeVersion.id, content, 'manual', principal.subjectId, '人工新建'); run.testCases.push(testCase); invalidateAudit(run); validateCurrentDependencyGraph(run); return presentCase(testCase) })
  }

  async getCase(projectVersionId: string, designId: string, runId: string, caseId: string) { const run = await this.loadScopedRun(projectVersionId, designId, runId); return presentCase(findCase(run, caseId), true) }
  async caseRevisions(projectVersionId: string, designId: string, runId: string, caseId: string) { const run = await this.loadScopedRun(projectVersionId, designId, runId); return structuredClone(findCase(run, caseId).revisions) }
  async caseDiff(projectVersionId: string, designId: string, runId: string, caseId: string, from: number, to: number) { const run = await this.loadScopedRun(projectVersionId, designId, runId); const testCase = findCase(run, caseId); const left = required(testCase.revisions.find(item => item.revision === from), 'TEST_CASE_REVISION_NOT_FOUND', '起始用例 revision 不存在'); const right = required(testCase.revisions.find(item => item.revision === to), 'TEST_CASE_REVISION_NOT_FOUND', '目标用例 revision 不存在'); return structuralDiff(left.content, right.content) }

  async patchCase(projectVersionId: string, designId: string, runId: string, caseId: string, ifMatch: string | undefined, input: { content: unknown; reason: string }, principal: Principal) {
    return this.store.transaction(state => {
      assertOpenVersion(state, projectVersionId); const run = findRun(state, projectVersionId, designId, runId); const testCase = findCase(run, caseId); if (testCase.reviewState === 'in_review') throw new TestDesignError('TEST_CASE_EDIT_LOCKED', '审核中的用例不能编辑', 409)
      const current = currentCaseRevision(testCase); assertEtag(ifMatch, etag('case', testCase.id, current.revision, current.contentSha256), 'TEST_CASE_REVISION_CONFLICT')
      const content = validateTestCaseContent(input.content, approvedPointIds(run, testCase.treeVersionId)); const revision = createCaseRevision(current.revision + 1, content, principal.subjectId, input.reason, current.content); testCase.revisions.push(revision); testCase.currentRevision = revision.revision; testCase.reviewState = 'draft'; if (testCase.origin === 'historical_unchanged') testCase.origin = 'historical_modified'; invalidateAudit(run); validateCurrentDependencyGraph(run); return presentCase(testCase, true)
    })
  }

  async deleteCase(projectVersionId: string, designId: string, runId: string, caseId: string, principal: Principal) { return this.store.transaction(state => { assertOpenVersion(state, projectVersionId); const run = findRun(state, projectVersionId, designId, runId); const testCase = findCase(run, caseId); testCase.tombstonedAt ??= now(); testCase.reviewState = 'draft'; invalidateAudit(run); validateCurrentDependencyGraph(run); return { caseId, deletedBy: principal.subjectId, tombstonedAt: testCase.tombstonedAt } }) }

  async reviewCase(projectVersionId: string, designId: string, runId: string, caseId: string, input: { decision: 'submit' | 'approve' | 'reject' | 'request_revision' | 'withdraw'; targetRevision: number; comment?: string }, principal: Principal) {
    return this.store.transaction(state => { assertOpenVersion(state, projectVersionId); const run = findRun(state, projectVersionId, designId, runId); const testCase = findCase(run, caseId); applyReviewAction(testCase, input, principal.subjectId); invalidateAudit(run); return presentCase(testCase, true) })
  }

  async batchReview(projectVersionId: string, designId: string, runId: string, input: { targets: Array<{ caseId: string; targetRevision: number }>; decision: 'submit' | 'approve' | 'reject' | 'request_revision' | 'withdraw'; comment?: string }, principal: Principal) {
    return this.store.transaction(state => { assertOpenVersion(state, projectVersionId); const run = findRun(state, projectVersionId, designId, runId); const targets = input.targets.map(target => ({ target, testCase: findCase(run, target.caseId) })); targets.forEach(({ target, testCase }) => { if (testCase.currentRevision !== target.targetRevision) throw new TestDesignError('TEST_CASE_REVISION_CONFLICT', `用例 ${testCase.id} revision 已变化`, 412) }); targets.forEach(({ target, testCase }) => applyReviewAction(testCase, { ...input, targetRevision: target.targetRevision }, principal.subjectId)); invalidateAudit(run); return targets.map(item => presentCase(item.testCase)) })
  }

  async getDataRequirements(projectVersionId: string, designId: string, runId: string) { const run = await this.loadScopedRun(projectVersionId, designId, runId); return structuredClone(run.dataSetVersions) }

  async replaceDataRequirements(projectVersionId: string, designId: string, runId: string, requirements: TestDataRequirement[], principal: Principal) {
    return this.store.transaction(state => { assertOpenVersion(state, projectVersionId); const run = findRun(state, projectVersionId, designId, runId); const normalized = validateDataRequirements(run, requirements); const version = dataSetVersion(run.dataSetVersions.length + 1, normalized, principal.subjectId); run.dataSetVersions.push(version); invalidateAudit(run); return structuredClone(version) })
  }

  async reAudit(projectVersionId: string, designId: string, runId: string) { return this.store.transaction(state => { const run = findRun(state, projectVersionId, designId, runId); const audit = runCoverageAudit(run); run.coverageAudits.forEach(item => { item.status = 'stale' }); run.coverageAudits.push(audit); return structuredClone(audit) }) }
  async coverageAudits(projectVersionId: string, designId: string, runId: string) { return structuredClone((await this.loadScopedRun(projectVersionId, designId, runId)).coverageAudits) }
  async coverageMatrix(projectVersionId: string, designId: string, runId: string, direction: 'basis_to_case' | 'case_to_basis') { const run = await this.loadScopedRun(projectVersionId, designId, runId); const audit = [...run.coverageAudits].reverse().find(item => item.status === 'valid'); if (!audit) throw new TestDesignError('COVERAGE_AUDIT_STALE', '没有有效覆盖审计', 409); return direction === 'basis_to_case' ? audit.relations : [...audit.relations].sort((left, right) => String(left.caseId).localeCompare(String(right.caseId))) }

  async basisSource(projectVersionId: string, designId: string, runId: string, basisItemId: string) { const run = await this.loadScopedRun(projectVersionId, designId, runId); return structuredClone(required(run.basisSnapshot.items.find(item => item.id === basisItemId), 'TEST_DESIGN_BASIS_ITEM_NOT_FOUND', '固定依据不存在')) }
  async retrievalSource(projectVersionId: string, designId: string, runId: string, hitId: string) { const run = await this.loadScopedRun(projectVersionId, designId, runId); return structuredClone(required(run.retrievalSnapshot.hits.find(item => item.id === hitId), 'TEST_DESIGN_RETRIEVAL_HIT_NOT_FOUND', '固定召回结果不存在')) }
  async historicalSource(projectVersionId: string, designId: string, runId: string, itemId: string) { const run = await this.loadScopedRun(projectVersionId, designId, runId); return structuredClone(required(run.historicalSnapshot.items.find(item => item.id === itemId), 'TEST_DESIGN_HISTORICAL_SOURCE_INVALID', '历史用例快照不存在')) }
  async findings(projectVersionId: string, designId: string, runId: string) { return structuredClone((await this.loadScopedRun(projectVersionId, designId, runId)).findings) }
  async confirmationItems(projectVersionId: string, designId: string, runId: string) { return structuredClone((await this.loadScopedRun(projectVersionId, designId, runId)).confirmationItems) }
  async actOnFinding(projectVersionId: string, designId: string, runId: string, findingId: string, input: { expectedVersion: number; decision: 'confirm' | 'resolve' | 'defer' | 'reject' | 'reopen'; comment?: string }, principal: Principal) { return this.store.transaction(state => { const run = findRun(state, projectVersionId, designId, runId); const finding = required(run.findings.find(item => item.id === findingId), 'TEST_DESIGN_FINDING_NOT_FOUND', '测试设计 Finding 不存在'); applyDisposition(finding, input, principal.subjectId); return structuredClone(finding) }) }
  async actOnConfirmation(projectVersionId: string, designId: string, runId: string, itemId: string, input: { expectedVersion: number; decision: 'confirm' | 'resolve' | 'defer' | 'reject' | 'reopen'; comment?: string; structuredDecision?: unknown }, principal: Principal) { return this.store.transaction(state => { const run = findRun(state, projectVersionId, designId, runId); const item = required(run.confirmationItems.find(candidate => candidate.id === itemId), 'TEST_DESIGN_CONFIRMATION_NOT_FOUND', '待确认项不存在'); applyDisposition(item, input, principal.subjectId); const requiredAction = item.impactStage === 'analysis' ? 'revise_scope' : item.impactStage === 'tree' ? 'revise_and_approve_tree' : item.impactStage === 'publication' ? 're_audit' : 'resynthesize'; return { item: structuredClone(item), requiredAction } }) }

  async publishCaseSet(projectVersionId: string, designId: string, runId: string, input: { name: string; expectedAuditId: string; expectedCaseSetSha256: string }, principal: Principal) {
    const published = await this.store.transaction(state => {
      assertOpenVersion(state, projectVersionId); const design = findDesign(state, projectVersionId, designId); const run = findRun(state, projectVersionId, designId, runId); const audit = required(run.coverageAudits.find(item => item.id === input.expectedAuditId && item.status === 'valid'), 'COVERAGE_AUDIT_STALE', '覆盖审计不存在或已失效')
      if (audit.blockers.length) throw new TestDesignError('TEST_CASE_SET_PUBLICATION_BLOCKED', '存在发布阻断项', 409, { blockers: audit.blockers })
      if (audit.caseSetSha256 !== input.expectedCaseSetSha256) throw new TestDesignError('TEST_CASE_SET_HASH_MISMATCH', '用例集合 Hash 与审计不一致', 409)
      const treeVersion = approvedTreeVersion(run); const dataSet = required(run.dataSetVersions.at(-1), 'TEST_CASE_NOT_READY', '数据需求版本不存在')
      const members = run.testCases.filter(item => !item.tombstonedAt).map((testCase, ordinal) => { const revision = currentCaseRevision(testCase); if (testCase.reviewState !== 'approved') throw new TestDesignError('TEST_CASE_REVIEW_REQUIRED', `用例 ${testCase.id} 未批准`, 409); return { caseId: testCase.id, revision: revision.revision, ordinal, contentSha256: revision.contentSha256 } })
      const canonicalContent = { schemaVersion: 'test-case-set/v1', projectVersionId, testDesignId: designId, runId, treeVersion: { id: treeVersion.id, sha256: treeVersion.treeSha256 }, dataSetVersion: { id: dataSet.id, sha256: dataSet.contentSha256 }, coverageAudit: { id: audit.id, inputSha256: audit.inputSha256 }, cases: members.map(member => ({ ...member, content: currentCaseRevision(findCase(run, member.caseId)).content })) }
      const contentSha256 = canonicalSha256(canonicalContent); const aggregate = designState(state); const existing = aggregate.caseSetVersions.find(item => item.testDesignId === designId && item.contentSha256 === contentSha256); if (existing) return structuredClone(existing)
      const version: TestCaseSetVersion = { id: `test_case_set_${randomUUID()}`, projectId: design.projectId, projectVersionId, testDesignId: designId, runId, version: Math.max(0, ...aggregate.caseSetVersions.filter(item => item.testDesignId === designId).map(item => item.version)) + 1, schemaVersion: 'test-case-set/v1', name: cleanRequired(input.name, '用例集名称', 200), treeVersionId: treeVersion.id, dataSetVersionId: dataSet.id, coverageAuditId: audit.id, members, canonicalContent, contentSha256, publishedBy: principal.subjectId, publishedAt: now(), projection: { status: 'pending' } }
      aggregate.caseSetVersions.push(version); return structuredClone(version)
    })
    if (published.projection.status === 'pending' && this.projector) await this.projectCaseSet(published.id, 'upload')
    return this.getCaseSet(published.id)
  }

  async getCaseSet(versionId: string) { const state = await this.store.snapshot(); return structuredClone(required(readDesignState(state).caseSetVersions.find(item => item.id === versionId), 'TEST_CASE_SET_NOT_FOUND', '用例集版本不存在')) }
  async retryCaseSetProjection(versionId: string) { const version = await this.getCaseSet(versionId); if (!this.projector) throw new TestDesignError('TEST_CASE_ASSET_PROJECTION_UNAVAILABLE', '知识资产投影服务不可用', 503); if (version.projection.status === 'succeeded') return version; await this.projectCaseSet(versionId, 'retry'); return this.getCaseSet(versionId) }
  async exportCaseSet(versionId: string, format: 'json' | 'markdown' | 'xlsx') { const version = await this.getCaseSet(versionId); if (format === 'json') return { contentType: 'application/json; charset=utf-8', fileName: `${version.id}.json`, content: `${canonicalJson(version.canonicalContent)}\n` }; if (format === 'markdown') return { contentType: 'text/markdown; charset=utf-8', fileName: `${version.id}.md`, content: markdownCaseSet(version) }; return { contentType: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet', fileName: `${version.id}.xlsx`, content: await xlsxCaseSet(version) } }

  async projectCatalog(projectId: string, filters: { domain?: string; executionMethod?: string; suiteVersionId?: string } = {}) {
    const state = await this.store.snapshot(); const aggregate = readDesignState(state); const suite = filters.suiteVersionId ? aggregate.suiteVersions.find(item => item.id === filters.suiteVersionId && item.projectId === projectId) : undefined
    const allowed = suite ? new Set(suite.members.map(item => `${item.testCaseSetVersionId}:${item.caseId}:${item.revision}`)) : null
    const items = aggregate.caseSetVersions.filter(item => item.projectId === projectId).flatMap(version => { const run = aggregate.runs.find(item => item.id === version.runId); if (!run) return []; return version.members.flatMap(member => { if (allowed && !allowed.has(`${version.id}:${member.caseId}:${member.revision}`)) return []; const testCase = run.testCases.find(item => item.id === member.caseId); const revision = testCase?.revisions.find(item => item.revision === member.revision); if (!revision || (filters.domain && revision.content.domain !== filters.domain) || (filters.executionMethod && !revision.content.executionMethods.some(method => method.method === filters.executionMethod))) return []; return [{ testCaseSetVersionId: version.id, testCaseSetName: version.name, caseId: member.caseId, revision: member.revision, content: revision.content, publishedAt: version.publishedAt, contentSha256: member.contentSha256 }] }) })
    return { items, catalogAsOf: now() }
  }

  async listSuites(projectId: string, suiteType?: string) { const state = await this.store.snapshot(); return structuredClone(readDesignState(state).suiteVersions.filter(item => item.projectId === projectId && (!suiteType || item.suiteType === suiteType)).sort(newest)) }
  async getSuite(projectId: string, suiteVersionId: string) { const state = await this.store.snapshot(); return structuredClone(required(readDesignState(state).suiteVersions.find(item => item.id === suiteVersionId && item.projectId === projectId), 'TEST_SUITE_VERSION_NOT_FOUND', '测试套件版本不存在')) }

  async reviewSmokeCandidate(versionId: string, caseId: string, input: { executionMethods: Array<'ui' | 'api'>; reason: string; estimatedMinutes: number; stable: boolean; dependencyReady: boolean; decision: 'accepted' | 'rejected' }, principal: Principal) {
    return this.store.transaction(state => { const aggregate = designState(state); const version = required(aggregate.caseSetVersions.find(item => item.id === versionId), 'TEST_CASE_SET_NOT_FOUND', '用例集版本不存在'); const run = required(aggregate.runs.find(item => item.id === version.runId), 'TEST_DESIGN_RUN_NOT_FOUND', '运行不存在'); assertMethodSubset(run, caseId, input.executionMethods); const relation: SmokeCandidateRelation = { caseId, executionMethods: input.executionMethods, reason: cleanRequired(input.reason, '候选理由', 2_000), estimatedMinutes: positive(input.estimatedMinutes, 'estimatedMinutes'), stable: input.stable === true, dependencyReady: input.dependencyReady === true, decision: input.decision, actorId: principal.subjectId, reviewedAt: now() }; run.smokeCandidates = [...run.smokeCandidates.filter(item => item.caseId !== caseId), relation]; return structuredClone(relation) })
  }

  async setImpactedRegression(versionId: string, values: Array<{ suiteVersionId: string; caseId: string; executionMethods: Array<'ui' | 'api'>; reason: string }>, principal: Principal) {
    return this.store.transaction(state => { const aggregate = designState(state); const version = required(aggregate.caseSetVersions.find(item => item.id === versionId), 'TEST_CASE_SET_NOT_FOUND', '用例集版本不存在'); const references: ImpactedRegressionReference[] = values.map(value => { const suite = required(aggregate.suiteVersions.find(item => item.id === value.suiteVersionId && item.projectId === version.projectId && item.suiteType === 'regression'), 'TEST_SUITE_VERSION_NOT_FOUND', '回归套件版本不存在'); const member = required(suite.members.find(item => item.caseId === value.caseId), 'TEST_SUITE_MEMBER_NOT_FOUND', '回归套件成员不存在'); if (!value.executionMethods.length || value.executionMethods.some(method => !member.executionMethods.includes(method))) throw new TestDesignError('TEST_CASE_EXECUTION_METHODS_SCHEMA_INVALID', '影响回归执行方式必须是套件成员方式的非空子集', 422); return { ...value, reason: cleanRequired(value.reason, '影响理由', 2_000), actorId: principal.subjectId, createdAt: now() } }); const run = required(aggregate.runs.find(item => item.id === version.runId), 'TEST_DESIGN_RUN_NOT_FOUND', '运行不存在'); run.impactedRegression = references; return structuredClone(references) })
  }

  async createHandoff(versionId: string, input: { strategy: 'standard' | 'fast' | 'full'; smokeSuiteVersionId?: string; regressionSuiteVersionId?: string; expectedCaseSetSha256: string }, principal: Principal) {
    return this.store.transaction(state => {
      const aggregate = designState(state); const version = required(aggregate.caseSetVersions.find(item => item.id === versionId), 'TEST_CASE_SET_NOT_FOUND', '用例集版本不存在'); if (version.contentSha256 !== input.expectedCaseSetSha256) throw new TestDesignError('TEST_CASE_SET_HASH_MISMATCH', '用例集 Hash 已变化', 409)
      const run = required(aggregate.runs.find(item => item.id === version.runId), 'TEST_DESIGN_RUN_NOT_FOUND', '运行不存在'); const smoke = input.smokeSuiteVersionId ? required(aggregate.suiteVersions.find(item => item.id === input.smokeSuiteVersionId && item.projectId === version.projectId && item.suiteType === 'smoke'), 'TEST_SUITE_VERSION_NOT_FOUND', '冒烟套件版本不存在') : undefined; const regression = input.regressionSuiteVersionId ? required(aggregate.suiteVersions.find(item => item.id === input.regressionSuiteVersionId && item.projectId === version.projectId && item.suiteType === 'regression'), 'TEST_SUITE_VERSION_NOT_FOUND', '回归套件版本不存在') : undefined
      const members: TestExecutionHandoff['members'] = []; const add = (stage: TestExecutionHandoff['members'][number]['stage'], sourceVersionId: string, caseId: string, revision: number, methods: Array<'ui' | 'api'>, reason: string) => methods.forEach(method => { const dedupKey = `${caseId}:${revision}:${method}`; if (!members.some(item => item.dedupKey === dedupKey)) members.push({ stage, ordinal: members.length, sourceVersionId, caseId, revision, method, reason, dedupKey }) })
      if (input.strategy !== 'fast') smoke?.members.forEach(item => add('smoke', smoke.id, item.caseId, item.revision, item.executionMethods, item.reason))
      if (input.strategy !== 'full') version.members.forEach(item => { const testCase = findCase(run, item.caseId); add('new_feature', version.id, item.caseId, item.revision, currentCaseRevision(testCase).content.executionMethods.map(method => method.method), '本次新功能用例') })
      if (input.strategy === 'standard') run.impactedRegression.forEach(item => { const suite = aggregate.suiteVersions.find(candidate => candidate.id === item.suiteVersionId)!; const member = suite.members.find(candidate => candidate.caseId === item.caseId)!; add('impacted_regression', suite.id, item.caseId, member.revision, item.executionMethods, item.reason) })
      if (input.strategy === 'full') regression?.members.forEach(item => add('full_regression', regression.id, item.caseId, item.revision, item.executionMethods, item.reason))
      const createdAt = now(); const base = { projectId: version.projectId, projectVersionId: version.projectVersionId, testCaseSetVersionId: version.id, strategy: input.strategy, ...(smoke ? { smokeSuiteVersionId: smoke.id } : {}), ...(regression ? { regressionSuiteVersionId: regression.id } : {}), members, createdBy: principal.subjectId, createdAt }; const handoff: TestExecutionHandoff = { id: `test_execution_handoff_${randomUUID()}`, ...base, contentSha256: canonicalSha256(base) }; aggregate.executionHandoffs.push(handoff); return structuredClone(handoff)
    })
  }

  async listHandoffs(versionId: string) { const state = await this.store.snapshot(); return structuredClone(readDesignState(state).executionHandoffs.filter(item => item.testCaseSetVersionId === versionId).sort(newest)) }
  async getHandoff(handoffId: string) { const state = await this.store.snapshot(); return structuredClone(required(readDesignState(state).executionHandoffs.find(item => item.id === handoffId), 'TEST_EXECUTION_HANDOFF_NOT_FOUND', '执行交接不存在')) }
  async smokeCandidates(versionId: string) { const state = await this.store.snapshot(); const aggregate = readDesignState(state); const version = required(aggregate.caseSetVersions.find(item => item.id === versionId), 'TEST_CASE_SET_NOT_FOUND', '用例集版本不存在'); return structuredClone(required(aggregate.runs.find(item => item.id === version.runId), 'TEST_DESIGN_RUN_NOT_FOUND', '运行不存在').smokeCandidates) }
  async impactedRegression(versionId: string) { const state = await this.store.snapshot(); const aggregate = readDesignState(state); const version = required(aggregate.caseSetVersions.find(item => item.id === versionId), 'TEST_CASE_SET_NOT_FOUND', '用例集版本不存在'); return structuredClone(required(aggregate.runs.find(item => item.id === version.runId), 'TEST_DESIGN_RUN_NOT_FOUND', '运行不存在').impactedRegression) }

  private async executeNode(runId: string, key: Exclude<TestDesignNodeKey, 'scope_gate' | 'tree_merge' | 'tree_gate' | 'coverage_audit'>, signal: AbortSignal, upstream: unknown) {
    await this.store.transaction(state => { const run = findRunById(state, runId); const target = node(run, key); Object.assign(target, { status: 'running', attempt: target.attempt + 1, startedAt: now(), finishedAt: undefined, error: undefined, errorCode: undefined, execution: undefined }); Object.assign(run, { status: 'running', stage: key, startedAt: run.startedAt ?? now() }) })
    const run = await this.loadRun(runId); return this.runtime!.execute({ stage: key, run, upstream }, signal)
  }
  private startLocally(runId: string) { if (this.activeRuns.has(runId)) return; const controller = new AbortController(); this.activeRuns.set(runId, controller); void this.processPreparedRun(runId, controller.signal).catch(() => undefined).finally(() => this.activeRuns.delete(runId)) }
  private async schedule(runId: string) { if (!this.store.enqueueTestDesignJob) { this.startLocally(runId); return } const run = await this.loadRun(runId); const target = run.nodeRuns.find(item => item.status === 'queued'); if (!target) return; const createdAt = now(); await this.store.enqueueTestDesignJob({ id: `workflow_job_${randomUUID()}`, runId, nodeRunId: target.id, status: 'queued', attempts: 0, maxAttempts: 3, availableAt: createdAt, createdAt, updatedAt: createdAt }) }
  private async loadRun(runId: string) { const state = await this.store.snapshot(); return structuredClone(findRunById(state, runId)) }
  private async loadScopedRun(projectVersionId: string, designId: string, runId: string) { const state = await this.store.snapshot(); return structuredClone(findRun(state, projectVersionId, designId, runId)) }
  private async projectCaseSet(versionId: string, trigger: 'upload' | 'retry') { const state = await this.store.snapshot(); const version = required(readDesignState(state).caseSetVersions.find(item => item.id === versionId), 'TEST_CASE_SET_NOT_FOUND', '用例集版本不存在'); const base = required(state.knowledgeBases.find(item => item.projectId === version.projectId), 'TEST_CASE_ASSET_PROJECTION_UNAVAILABLE', '项目知识库不存在'); try { const result = await this.projector!.ingest({ knowledgeBaseId: base.id, sourceType: 'upload', sourceKey: `test-case-set:${version.id}:${version.contentSha256}`, assetType: 'test_case', displayName: `${version.name} v${version.version}`, logicalPath: `test-cases/${version.id}.md`, content: markdownCaseSet(version), taskTrigger: trigger }); await this.store.transaction(draft => { const target = required(designState(draft).caseSetVersions.find(item => item.id === versionId), 'TEST_CASE_SET_NOT_FOUND', '用例集版本不存在'); target.projection = { status: result.task ? 'pending' : 'succeeded', assetVersionId: result.version.id } }) } catch (error) { await this.store.transaction(draft => { const target = required(designState(draft).caseSetVersions.find(item => item.id === versionId), 'TEST_CASE_SET_NOT_FOUND', '用例集版本不存在'); target.projection = { status: 'failed', error: error instanceof Error ? error.message.slice(0, 2_000) : String(error).slice(0, 2_000) } }) } }
}

function workflowNodes(runId: string): WorkflowNodeRun[] { const definition: Array<[TestDesignNodeKey, TestDesignNodeKey[]]> = [['test_analysis', []], ['scope_gate', ['test_analysis']], ['functional_design', ['scope_gate']], ['non_functional_design', ['scope_gate']], ['tree_merge', ['functional_design', 'non_functional_design']], ['tree_gate', ['tree_merge']], ['test_case_synthesis', ['tree_gate']], ['coverage_audit', ['test_case_synthesis']]]; return definition.map(([nodeKey, dependencies]) => ({ id: `${runId}:${nodeKey}:g1:a0`, nodeKey, generation: 1, attempt: 0, status: nodeKey === 'test_analysis' ? 'queued' : 'pending', dependencies })) }
function materializeAnalysisIssues(run: TestDesignWorkflowRun, raw: unknown) { const value = raw && typeof raw === 'object' ? raw as { findings?: unknown[]; confirmationItems?: unknown[] } : {}; run.findings = (Array.isArray(value.findings) ? value.findings : []).slice(0, 500).map((candidate, index) => { const item = candidate && typeof candidate === 'object' ? candidate as Record<string, unknown> : {}; return { id: `test_design_finding_${randomUUID()}`, title: cleanRequired(String(item.title ?? `Finding ${index + 1}`), 'Finding 标题', 500), description: String(item.description ?? item.problem ?? '').slice(0, 8_000), severity: ['blocker', 'high', 'medium', 'low'].includes(String(item.severity)) ? item.severity as 'blocker' | 'high' | 'medium' | 'low' : 'medium', basisRefs: Array.isArray(item.basisRefs) ? item.basisRefs.map(String) : [], state: 'open' as const, actions: [] } }); run.confirmationItems = (Array.isArray(value.confirmationItems) ? value.confirmationItems : []).slice(0, 500).map((candidate, index) => { const item = candidate && typeof candidate === 'object' ? candidate as Record<string, unknown> : {}; return { id: `test_design_confirmation_${randomUUID()}`, title: cleanRequired(String(item.title ?? `待确认项 ${index + 1}`), '待确认项标题', 500), question: String(item.question ?? '').slice(0, 8_000), decisionType: String(item.decisionType ?? 'other').slice(0, 200), impactStage: ['analysis', 'tree', 'case', 'data', 'publication'].includes(String(item.impactStage)) ? item.impactStage as 'analysis' | 'tree' | 'case' | 'data' | 'publication' : 'publication', affectedRefs: Array.isArray(item.affectedRefs) ? item.affectedRefs.map(String) : [], blocker: item.blocker === true, state: 'open' as const, actions: [] } }) }
function buildBasisSnapshot(state: DatabaseState, design: TestDesign, createdAt: string): TestDesignBasisSnapshot { const items = design.input.basisMode === 'review_baseline' ? reviewBasisItems(state, design.input.sourceReviewRunId, design.input.sourceTechnicalSolutionRunId) : design.input.knowledgeAssetVersionIds.map(id => assetContentRef(state, design.projectId, id, 'knowledge_asset')); const base = { schemaVersion: 'test-design-basis-snapshot/v1' as const, basisMode: design.basisMode, projectVersionId: design.projectVersionId, items, createdAt }; return { ...base, snapshotSha256: canonicalSha256(base) } }
function reviewBasisItems(state: DatabaseState, reviewRunId: string, technicalRunId: string) { const review = required(state.reviewRuns.find(item => item.id === reviewRunId && item.status === 'succeeded' && item.result), 'TEST_DESIGN_REVIEW_CHAIN_INVALID', '需求评审基线无效'); const technical = required(state.technicalSolutionRuns.find(item => item.id === technicalRunId && item.status === 'succeeded' && item.result && item.sourceReviewRunId === reviewRunId), 'TEST_DESIGN_REVIEW_CHAIN_INVALID', '技术方案评审链无效'); return [{ id: `basis_requirement_${review.id}`, kind: 'requirement_review' as const, sourceId: review.id, contentSha256: canonicalSha256(review.result), content: structuredClone(review.result) }, { id: `basis_technical_${technical.id}`, kind: 'technical_solution_review' as const, sourceId: technical.id, contentSha256: canonicalSha256(technical.result), content: structuredClone(technical.result) }] }
function buildRetrievalSnapshot(state: DatabaseState, design: TestDesign, createdAt: string): RetrievalSnapshot { const augmentation = design.input.knowledgeAugmentation; const assetVersionIds = augmentation.mode === 'selected_assets' ? augmentation.assetVersionIds : augmentation.mode === 'fixed_index' ? (state.indexes.find(item => item.id === augmentation.indexVersionId)?.assetVersionIds ?? []) : []; assetVersionIds.forEach(id => assetContentRef(state, design.projectId, id, 'knowledge_asset')); const base = { canonicalVersion: 'retrieval-snapshot/v1' as const, mode: augmentation.mode, assetVersionIds, ...(augmentation.mode === 'fixed_index' ? { indexVersionId: augmentation.indexVersionId, ...(augmentation.filters ? { filters: augmentation.filters } : {}) } : {}), queryPlan: [], hits: [], createdAt }; return { ...base, snapshotSha256: canonicalSha256(base) } }
function buildHistoricalSnapshot(state: DatabaseState, design: TestDesign, createdAt: string): HistoricalCaseSnapshot { const aggregate = readDesignState(state); const items: HistoricalCaseSnapshot['items'] = []; for (const selection of design.input.historicalCaseSelections ?? []) { if (selection.sourceType === 'asset_version') { items.push(assetContentRef(state, design.projectId, selection.assetVersionId!, 'historical_case_asset')); continue } for (const caseId of selection.caseIds!) { const version = required(aggregate.caseSetVersions.find(item => item.id === selection.testCaseSetVersionId && item.projectId === design.projectId), 'TEST_DESIGN_HISTORICAL_SOURCE_INVALID', '历史用例集不存在'); const member = required(version.members.find(item => item.caseId === caseId), 'TEST_DESIGN_HISTORICAL_SOURCE_INVALID', '历史用例不存在'); const sourceRun = required(aggregate.runs.find(item => item.id === version.runId), 'TEST_DESIGN_HISTORICAL_SOURCE_INVALID', '历史用例运行不存在'); const sourceCase = findCase(sourceRun, member.caseId); const revision = sourceCase.revisions.find(item => item.revision === member.revision)!; items.push({ id: `history_${version.id}_${caseId}`, kind: 'historical_case_set', sourceId: `${version.id}:${caseId}:${member.revision}`, contentSha256: revision.semanticSha256, content: structuredClone(revision.content), locator: { testCaseSetVersionId: version.id, caseId, revision: member.revision } }) } } const base = { schemaVersion: 'historical-case-snapshot/v1' as const, items, createdAt }; return { ...base, snapshotSha256: canonicalSha256(base) } }
function assetContentRef(state: DatabaseState, projectId: string, versionId: string, kind: 'knowledge_asset' | 'historical_case_asset') { const version = required(state.versions.find(item => item.id === versionId && item.status === 'ready'), 'TEST_DESIGN_ASSET_NOT_READY', `资产版本 ${versionId} 不存在或未就绪`); const asset = required(state.assets.find(item => item.id === version.assetId), 'TEST_DESIGN_ASSET_NOT_READY', '资产不存在'); const base = required(state.knowledgeBases.find(item => item.id === asset.knowledgeBaseId && item.projectId === projectId), 'TEST_DESIGN_HISTORICAL_SOURCE_INVALID', '资产不属于当前项目'); return { id: `basis_asset_${version.id}`, kind, sourceId: version.id, contentSha256: version.contentHash, content: { assetId: asset.id, assetVersionId: version.id, assetType: asset.assetType, displayName: asset.displayName, logicalPath: asset.logicalPath, content: version.content, chunks: version.chunks }, locator: { projectId, knowledgeBaseId: base.id, assetId: asset.id, assetVersionId: version.id, logicalPath: asset.logicalPath } } }
function validateDesignSources(state: DatabaseState, projectId: string, projectVersionId: string, input: CreateTestDesignInput) { if (input.basisMode === 'review_baseline') { const review = required(state.reviewRuns.find(item => item.id === input.sourceReviewRunId && item.projectVersionId === projectVersionId && item.status === 'succeeded' && item.result), 'TEST_DESIGN_REVIEW_CHAIN_INVALID', '需求评审基线无效'); required(state.technicalSolutionRuns.find(item => item.id === input.sourceTechnicalSolutionRunId && item.projectVersionId === projectVersionId && item.sourceReviewRunId === review.id && item.status === 'succeeded' && item.result), 'TEST_DESIGN_REVIEW_CHAIN_INVALID', '技术方案评审链无效') } else input.knowledgeAssetVersionIds.forEach(id => assetContentRef(state, projectId, id, 'knowledge_asset')); if (input.knowledgeAugmentation.mode === 'selected_assets') input.knowledgeAugmentation.assetVersionIds.forEach(id => assetContentRef(state, projectId, id, 'knowledge_asset')); if (input.knowledgeAugmentation.mode === 'fixed_index') { const indexVersionId = input.knowledgeAugmentation.indexVersionId; const index = required(state.indexes.find(item => item.id === indexVersionId && item.status === 'active'), 'TEST_DESIGN_AUGMENTATION_INVALID', '固定索引不存在或未激活'); const base = required(state.knowledgeBases.find(item => item.id === index.knowledgeBaseId), 'TEST_DESIGN_AUGMENTATION_INVALID', '固定索引知识库不存在'); if (base.projectId !== projectId) throw new TestDesignError('TEST_DESIGN_AUGMENTATION_INVALID', '固定索引不属于当前项目') } }
function mergeTree(run: TestDesignWorkflowRun, functionalRaw: unknown, nonFunctionalRaw: unknown, actorId: string) { const functional = validateDesignCandidateNodes(functionalRaw, 'functional').map(candidate => ({ scope: 'functional', candidate })); const nonFunctional = validateDesignCandidateNodes(nonFunctionalRaw, 'non_functional').map(candidate => ({ scope: 'non_functional', candidate })); const all = [...functional, ...nonFunctional]; const scopedRef = (scope: string, ref: string) => `${scope}:${ref}`; const idByRef = new Map(all.map(item => [scopedRef(item.scope, item.candidate.ref), `test_point_${randomUUID()}`])); const nodes: TestPointNodeRevision[] = all.map((item, index) => { const { scope, candidate } = item; return { nodeId: idByRef.get(scopedRef(scope, candidate.ref))!, parentId: candidate.parentRef ? idByRef.get(scopedRef(scope, candidate.parentRef)) ?? null : null, sortKey: `${String(index + 1).padStart(6, '0')}:${scope}:${candidate.ref}`, title: candidate.title, objective: candidate.objective, dimension: candidate.dimension, priority: candidate.priority, applicability: candidate.applicability, designTechniques: candidate.designTechniques, entryMethods: candidate.entryMethods, oracle: candidate.oracle, dataConditions: candidate.dataConditions, risks: candidate.risks, assumptions: candidate.assumptions, basisRefs: candidate.basisRefs, historicalRefs: candidate.historicalRefs } }); const treeSha256 = validateTreeNodes(nodes); run.testPointTree = { id: `test_point_tree_${randomUUID()}`, runId: run.id, currentRevision: 0, revisions: [{ revision: 0, parentRevision: null, nodes, operations: [], reason: 'Agent 候选归并', actorId, treeSha256, createdAt: now() }], versions: [] } }
function materializeSynthesis(run: TestDesignWorkflowRun, raw: unknown, actorId: string) { const value = raw as SynthesisResult; if (!value || typeof value !== 'object' || !Array.isArray(value.cases) || !Array.isArray(value.dataRequirements)) throw new TestDesignError('TEST_CASE_SYNTHESIS_SCHEMA_INVALID', '综合结果缺少 cases 或 dataRequirements', 422); const treeVersion = approvedTreeVersion(run); const points = approvedPointIds(run, treeVersion.id); const cases = value.cases.map(content => newCase(run.id, treeVersion.id, validateTestCaseContent(content, points), 'ai', actorId, 'Agent 候选')); const requirements = value.dataRequirements.map(candidate => ({ id: `test_data_${randomUUID()}`, name: candidate.name, entityType: candidate.entityType, featureTags: candidate.featureTags, testPointIds: candidate.testPointIds, caseIds: candidate.caseIndexes.map(index => required(cases[index]?.id, 'TEST_DATA_REQUIREMENT_CASE_INVALID', '数据需求引用的用例索引无效')), fieldConstraints: candidate.fieldConstraints, relationships: candidate.relationships, quantity: candidate.quantity, initialState: candidate.initialState, preparationHint: candidate.preparationHint, sensitivity: candidate.sensitivity, isolation: candidate.isolation, resetAndCleanup: candidate.resetAndCleanup, readiness: candidate.readiness, ...(candidate.readinessReason ? { readinessReason: candidate.readinessReason } : {}) })); run.testCases = cases; run.dataSetVersions = [dataSetVersion(1, validateDataRequirements(run, requirements), actorId)] }
function runCoverageAudit(run: TestDesignWorkflowRun): CoverageAudit { const tree = required(run.testPointTree, 'TEST_POINT_TREE_APPROVAL_REQUIRED', '测试点树不存在'); const version = approvedTreeVersion(run); const dataSet = required(run.dataSetVersions.at(-1), 'TEST_CASE_NOT_READY', '数据需求版本不存在'); return auditTestDesignCoverage({ runId: run.id, basis: run.basisSnapshot, tree, treeVersion: version, cases: run.testCases, dataSet }) }
function validateDataRequirements(run: TestDesignWorkflowRun, requirements: TestDataRequirement[]) { const caseIds = new Set(run.testCases.filter(item => !item.tombstonedAt).map(item => item.id)); const pointIds = approvedPointIds(run, approvedTreeVersion(run).id); const ids = new Set<string>(); return requirements.map(requirement => { if (!requirement.id || ids.has(requirement.id)) throw new TestDesignError('TEST_DATA_REQUIREMENT_SCHEMA_INVALID', '数据需求 ID 缺失或重复', 422); ids.add(requirement.id); if (!requirement.name?.trim() || !requirement.entityType?.trim() || !Number.isInteger(requirement.quantity) || requirement.quantity < 1) throw new TestDesignError('TEST_DATA_REQUIREMENT_SCHEMA_INVALID', '数据需求基础字段无效', 422); if (requirement.caseIds.some(id => !caseIds.has(id)) || requirement.testPointIds.some(id => !pointIds.has(id))) throw new TestDesignError('TEST_DATA_REQUIREMENT_REFERENCE_INVALID', '数据需求引用不属于当前运行', 422); const serialized = canonicalJson(requirement); if (/(api[_ -]?key|authorization|cookie|token|身份证|真实账号)\s*[:=]\s*[^<\s]/iu.test(serialized)) throw new TestDesignError('TEST_DATA_REQUIREMENT_SECRET_FORBIDDEN', '数据需求不能包含真实凭据或个人敏感数据', 422); return structuredClone(requirement) }) }
function dataSetVersion(version: number, requirements: TestDataRequirement[], actorId: string): TestDataRequirementSetVersion { return { id: `test_data_set_${randomUUID()}`, version, requirements: structuredClone(requirements), contentSha256: canonicalSha256(requirements), createdBy: actorId, createdAt: now() } }
function newCase(runId: string, treeVersionId: string, content: TestCaseContent, origin: TestCase['origin'], actorId: string, reason: string): TestCase { const revision = createCaseRevision(0, content, actorId, reason); return { id: `test_case_${randomUUID()}`, runId, treeVersionId, origin, currentRevision: 0, reviewState: 'draft', revisions: [revision], reviewActions: [] } }
function createCaseRevision(revision: number, content: TestCaseContent, actorId: string, reason: string, previous?: TestCaseContent) { return { revision, content: structuredClone(content), contentSha256: canonicalSha256(content), semanticSha256: canonicalSha256({ ...content, tags: [...content.tags].sort() }), diff: previous ? structuralDiff(previous, content) : [], editorId: actorId, reason: cleanRequired(reason, '保存说明', 2_000), createdAt: now() } }
function structuralDiff(before: unknown, after: unknown, path = ''): Array<{ path: string; before?: unknown; after?: unknown }> { if (canonicalSha256(before) === canonicalSha256(after)) return []; if (!before || !after || typeof before !== 'object' || typeof after !== 'object' || Array.isArray(before) || Array.isArray(after)) return [{ path: path || '/', before, after }]; const left = before as Record<string, unknown>; const right = after as Record<string, unknown>; return [...new Set([...Object.keys(left), ...Object.keys(right)])].sort().flatMap(key => structuralDiff(left[key], right[key], `${path}/${key}`)) }
function applyTreeOperations(current: TestPointNodeRevision[], operations: TestPointTreeOperation[]) { const nodes = structuredClone(current); const active = (id: string) => required(nodes.find(item => item.nodeId === id && !item.deleted), 'TEST_POINT_NOT_FOUND', `测试点 ${id} 不存在`); for (const operation of operations) { if (operation.op === 'add') { if (operation.parentId) active(operation.parentId); nodes.push({ nodeId: `test_point_${randomUUID()}`, parentId: operation.parentId, sortKey: cleanRequired(operation.sortKey, 'sortKey', 200), ...structuredClone(operation.value) }) } else if (operation.op === 'rename') active(operation.nodeId).title = cleanRequired(operation.title, 'title', 500); else if (operation.op === 'update') Object.assign(active(operation.nodeId), structuredClone(operation.patch), { nodeId: operation.nodeId }); else if (operation.op === 'move') { const node = active(operation.nodeId); if (operation.parentId) active(operation.parentId); node.parentId = operation.parentId; node.sortKey = cleanRequired(operation.sortKey, 'sortKey', 200) } else if (operation.op === 'delete') { const target = active(operation.nodeId); target.deleted = true; nodes.filter(item => item.parentId === target.nodeId && !item.deleted).forEach(item => { item.parentId = target.parentId }) } else if (operation.op === 'mark_not_applicable') { const target = active(operation.nodeId); target.applicability = 'not_applicable'; target.assumptions = [...target.assumptions, cleanRequired(operation.reason, 'reason', 2_000)] } else if (operation.op === 'reorder') active(operation.nodeId).sortKey = cleanRequired(operation.sortKey, 'sortKey', 200); else if (operation.op === 'split') { const target = active(operation.nodeId); operation.children.forEach(child => nodes.push({ nodeId: `test_point_${randomUUID()}`, parentId: target.parentId, sortKey: child.sortKey, ...structuredClone(child.value) })); target.deleted = true } else if (operation.op === 'merge') { const target = active(operation.targetNodeId); operation.sourceNodeIds.filter(id => id !== target.nodeId).forEach(id => { active(id).deleted = true }); Object.assign(target, structuredClone(operation.value), { nodeId: target.nodeId }) } } validateTreeNodes(nodes); return nodes }
function approveCurrentTree(run: TestDesignWorkflowRun, actorId: string) { const tree = required(run.testPointTree, 'TEST_POINT_TREE_APPROVAL_REQUIRED', '测试点树不存在'); const revision = tree.revisions.find(item => item.revision === tree.currentRevision)!; const existing = tree.versions.find(item => item.revision === revision.revision && item.treeSha256 === revision.treeSha256); if (existing) { tree.currentApprovedVersionId = existing.id; return existing } const version = { id: `test_point_tree_version_${randomUUID()}`, version: Math.max(0, ...tree.versions.map(item => item.version)) + 1, revision: revision.revision, treeSha256: revision.treeSha256, approvedBy: actorId, approvedAt: now() }; tree.versions.push(version); tree.currentApprovedVersionId = version.id; return version }
function approvedTreeVersion(run: TestDesignWorkflowRun) { const tree = required(run.testPointTree, 'TEST_POINT_TREE_APPROVAL_REQUIRED', '测试点树不存在'); return required(tree.versions.find(item => item.id === tree.currentApprovedVersionId), 'TEST_POINT_TREE_APPROVAL_REQUIRED', '测试点树未批准') }
function approvedPointIds(run: TestDesignWorkflowRun, treeVersionId: string) { const tree = required(run.testPointTree, 'TEST_POINT_TREE_APPROVAL_REQUIRED', '测试点树不存在'); const version = required(tree.versions.find(item => item.id === treeVersionId), 'TEST_POINT_TREE_APPROVAL_REQUIRED', '测试点树版本不存在'); const revision = tree.revisions.find(item => item.revision === version.revision)!; return new Set(revision.nodes.filter(item => !item.deleted && item.applicability !== 'not_applicable').map(item => item.nodeId)) }
function applyReviewAction(testCase: TestCase, input: { decision: 'submit' | 'approve' | 'reject' | 'request_revision' | 'withdraw'; targetRevision: number; comment?: string }, actorId: string) { if (testCase.currentRevision !== input.targetRevision) throw new TestDesignError('TEST_CASE_REVISION_CONFLICT', '审核目标 revision 已变化', 412); const transitions = { draft: { submit: 'in_review' }, in_review: { approve: 'approved', reject: 'rejected', request_revision: 'needs_revision', withdraw: 'draft' }, approved: { request_revision: 'needs_revision' }, rejected: { submit: 'in_review' }, needs_revision: { submit: 'in_review' } } as const; const toState = (transitions[testCase.reviewState] as Record<string, TestCase['reviewState'] | undefined>)[input.decision]; if (!toState) throw new TestDesignError('TEST_CASE_REVIEW_TRANSITION_INVALID', `不能从 ${testCase.reviewState} 执行 ${input.decision}`, 409); testCase.reviewActions.push({ id: `test_case_review_${randomUUID()}`, targetRevision: input.targetRevision, fromState: testCase.reviewState, toState, decision: input.decision, ...(input.comment?.trim() ? { comment: input.comment.trim().slice(0, 4_000) } : {}), actorId, createdAt: now() }); testCase.reviewState = toState }
function applyDisposition(target: { state: 'open' | 'confirmed' | 'resolved' | 'deferred' | 'rejected'; actions: Array<{ id: string; expectedVersion: number; fromState: string; toState: string; decision: string; comment?: string; structuredDecision?: unknown; actorId: string; createdAt: string }> }, input: { expectedVersion: number; decision: 'confirm' | 'resolve' | 'defer' | 'reject' | 'reopen'; comment?: string; structuredDecision?: unknown }, actorId: string) { if (target.actions.length !== input.expectedVersion) throw new TestDesignError('TEST_DESIGN_DISPOSITION_VERSION_CONFLICT', '处置版本已变化', 409); const toState = input.decision === 'confirm' ? 'confirmed' : input.decision === 'resolve' ? 'resolved' : input.decision === 'defer' ? 'deferred' : input.decision === 'reject' ? 'rejected' : 'open'; target.actions.push({ id: `test_design_action_${randomUUID()}`, expectedVersion: input.expectedVersion, fromState: target.state, toState, decision: input.decision, ...(input.comment?.trim() ? { comment: input.comment.trim().slice(0, 4_000) } : {}), ...(input.structuredDecision === undefined ? {} : { structuredDecision: structuredClone(input.structuredDecision) }), actorId, createdAt: now() }); target.state = toState }
function validateCurrentDependencyGraph(run: TestDesignWorkflowRun) { validateCaseDependencyGraph(run.testCases.filter(item => !item.tombstonedAt).map(item => ({ id: item.id, content: currentCaseRevision(item).content }))) }
function invalidateAudit(run: TestDesignWorkflowRun) { run.coverageAudits.forEach(item => { item.status = 'stale' }) }
function assertMethodSubset(run: TestDesignWorkflowRun, caseId: string, methods: Array<'ui' | 'api'>) { if (!methods.length) throw new TestDesignError('TEST_CASE_EXECUTION_METHODS_SCHEMA_INVALID', '执行方式子集不能为空', 422); const content = currentCaseRevision(findCase(run, caseId)).content; const available = new Set(content.executionMethods.filter(method => method.executionReadiness === 'ready').map(method => method.method)); if (methods.some(method => !available.has(method))) throw new TestDesignError('TEST_CASE_EXECUTION_METHODS_SCHEMA_INVALID', '执行方式不是来源用例 ready 方式的子集', 422) }
function publishArtifact(run: TestDesignWorkflowRun, key: TestDesignNodeKey, output: { schemaVersion: string; content: unknown }) { const target = node(run, key); const artifactValue: WorkflowArtifact = { id: `workflow_artifact_${randomUUID()}`, nodeKey: key, schemaVersion: output.schemaVersion, generation: target.generation, content: structuredClone(output.content), contentSha256: canonicalSha256(output.content), createdAt: now() }; run.artifacts.push(artifactValue); target.outputArtifactId = artifactValue.id }
function artifact(run: TestDesignWorkflowRun, key: TestDesignNodeKey) { const target = node(run, key); return required(run.artifacts.find(item => item.id === target.outputArtifactId), 'WORKFLOW_ARTIFACT_HASH_MISMATCH', `${key} 产物不存在`) }
function startGate(run: TestDesignWorkflowRun, key: 'scope_gate' | 'tree_gate', target: unknown) { const gate = node(run, key); Object.assign(gate, { status: 'waiting_gate', startedAt: now(), inputSha256: canonicalSha256(target) }) }
function finishNode(run: TestDesignWorkflowRun, key: TestDesignNodeKey, execution?: WorkflowNodeRun['execution']) { const target = node(run, key); Object.assign(target, { status: 'succeeded', finishedAt: now(), ...(execution ? { execution } : {}) }) }
function failNode(run: TestDesignWorkflowRun, key: TestDesignNodeKey, error: unknown) { const target = node(run, key); const message = error instanceof Error ? error.message : String(error); const execution = error && typeof error === 'object' && 'execution' in error ? (error as { execution?: WorkflowNodeRun['execution'] }).execution : undefined; Object.assign(target, { status: 'failed', finishedAt: now(), error: message, errorCode: errorCode(message), ...(execution ? { execution } : {}) }) }
function queueNode(run: TestDesignWorkflowRun, key: TestDesignNodeKey) { const target = node(run, key); Object.assign(target, { status: 'queued', error: undefined, errorCode: undefined }) }
function node(run: TestDesignWorkflowRun, key: TestDesignNodeKey) { return required(run.nodeRuns.find(item => item.nodeKey === key), 'WORKFLOW_NODE_NOT_FOUND', `${key} 节点不存在`) }
function latestApprovedGate(run: TestDesignWorkflowRun, gate: 'scope' | 'test-point-tree') { return [...run.gateDecisions].reverse().find(item => item.gateKey === gate)?.decision === 'approved' }
function currentCaseRevision(testCase: TestCase) { return required(testCase.revisions.find(item => item.revision === testCase.currentRevision), 'TEST_CASE_REVISION_NOT_FOUND', '用例当前 revision 不存在') }
function findCase(run: TestDesignWorkflowRun, caseId: string) { return required(run.testCases.find(item => item.id === caseId), 'TEST_CASE_NOT_FOUND', '测试用例不存在') }
function findDesign(state: DatabaseState, projectVersionId: string, designId: string) { return required(readDesignState(state).designs.find(item => item.id === designId && item.projectVersionId === projectVersionId), 'TEST_DESIGN_NOT_FOUND', '测试设计不存在') }
function findRun(state: DatabaseState, projectVersionId: string, designId: string, runId: string) { findDesign(state, projectVersionId, designId); return required(readDesignState(state).runs.find(item => item.id === runId && item.testDesignId === designId && item.projectVersionId === projectVersionId), 'TEST_DESIGN_RUN_NOT_FOUND', '测试设计运行不存在') }
function findRunById(state: DatabaseState, runId: string) { return required(designState(state).runs.find(item => item.id === runId), 'TEST_DESIGN_RUN_NOT_FOUND', '测试设计运行不存在') }
function assertOpenVersion(state: DatabaseState, projectVersionId: string) { const version = required(state.projectVersions.find(item => item.id === projectVersionId), 'PROJECT_VERSION_NOT_FOUND', '项目版本不存在'); if (version.status !== 'open') throw new TestDesignError('PROJECT_VERSION_READ_ONLY', '当前项目版本只读', 409) }
function designState(state: DatabaseState): TestDesignState { return state.testDesignState ??= { designs: [], runs: [], caseSetVersions: [], suiteVersions: [], executionHandoffs: [] } }
function readDesignState(state: DatabaseState): TestDesignState { return state.testDesignState ?? { designs: [], runs: [], caseSetVersions: [], suiteVersions: [], executionHandoffs: [] } }
function presentRun(run: TestDesignWorkflowRun, detail = false) { const value = structuredClone(run); if (!detail) return { id: value.id, testDesignId: value.testDesignId, projectVersionId: value.projectVersionId, status: value.status, stage: value.stage, progress: value.progress, createdAt: value.createdAt, startedAt: value.startedAt, finishedAt: value.finishedAt, errorCode: value.errorCode, error: value.error }; return value }
function presentCase(testCase: TestCase, detail = false) { const revision = currentCaseRevision(testCase); const value = { id: testCase.id, runId: testCase.runId, treeVersionId: testCase.treeVersionId, origin: testCase.origin, currentRevision: testCase.currentRevision, reviewState: testCase.reviewState, content: structuredClone(revision.content), contentSha256: revision.contentSha256, etag: etag('case', testCase.id, revision.revision, revision.contentSha256), ...(detail ? { revisions: structuredClone(testCase.revisions), reviewActions: structuredClone(testCase.reviewActions), tombstonedAt: testCase.tombstonedAt } : {}) }; return value }
function markdownCaseSet(version: TestCaseSetVersion) { const content = version.canonicalContent as { cases: Array<{ caseId: string; revision: number; content: TestCaseContent }> }; return [`# ${version.name}`, '', `- Version: ${version.version}`, `- Schema: ${version.schemaVersion}`, `- Content SHA-256: ${version.contentSha256}`, '', ...content.cases.flatMap(item => [`## ${item.caseId} r${item.revision}: ${item.content.title}`, '', item.content.objective, '', `- Dimension: ${item.content.dimension}`, `- Priority: ${item.content.priority}`, `- Methods: ${item.content.executionMethods.map(method => method.method).join(', ')}`, ''])].join('\n') }
async function xlsxCaseSet(version: TestCaseSetVersion) { const value = version.canonicalContent as { cases: Array<{ caseId: string; revision: number; content: TestCaseContent }> }; const rows = [['Case ID', 'Revision', 'Title', 'Objective', 'Dimension', 'Priority', 'Methods', 'Domain', 'Preconditions', 'Steps', 'Checks'], ...value.cases.map(item => [item.caseId, String(item.revision), item.content.title, item.content.objective, item.content.dimension, item.content.priority, item.content.executionMethods.map(method => method.method).join(', '), item.content.domain, item.content.preconditions.join('\n'), item.content.executionMethods.flatMap(method => method.steps.map(step => `[${method.method}] ${step.key}: ${step.action} => ${step.expected}`)).join('\n'), item.content.executionMethods.flatMap(method => method.verificationChecks.map(check => `[${method.method}] ${check.description}`)).concat(item.content.sharedVerificationChecks.map(check => `[shared] ${check.description}`)).join('\n')])]; const sheetRows = rows.map((row, rowIndex) => `<row r="${rowIndex + 1}">${row.map((cell, columnIndex) => `<c r="${columnName(columnIndex + 1)}${rowIndex + 1}" t="inlineStr"${rowIndex === 0 ? ' s="1"' : ''}><is><t xml:space="preserve">${xml(safeSpreadsheetText(cell))}</t></is></c>`).join('')}</row>`).join(''); const zip = new JSZip(); zip.file('[Content_Types].xml', '<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/><Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/></Types>'); zip.file('_rels/.rels', '<?xml version="1.0" encoding="UTF-8"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>'); zip.file('xl/workbook.xml', '<?xml version="1.0" encoding="UTF-8"?><workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets><sheet name="Test Cases" sheetId="1" r:id="rId1"/></sheets></workbook>'); zip.file('xl/_rels/workbook.xml.rels', '<?xml version="1.0" encoding="UTF-8"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/><Relationship Id="rId2" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/></Relationships>'); zip.file('xl/styles.xml', '<?xml version="1.0" encoding="UTF-8"?><styleSheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><fonts count="2"><font/><font><b/></font></fonts><fills count="1"><fill><patternFill patternType="none"/></fill></fills><borders count="1"><border/></borders><cellStyleXfs count="1"><xf/></cellStyleXfs><cellXfs count="2"><xf xfId="0"/><xf xfId="0" fontId="1" applyFont="1"/></cellXfs></styleSheet>'); zip.file('xl/worksheets/sheet1.xml', `<?xml version="1.0" encoding="UTF-8"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetData>${sheetRows}</sheetData></worksheet>`); return zip.generateAsync({ type: 'nodebuffer', compression: 'DEFLATE' }) }
function columnName(index: number) { let name = ''; for (let value = index; value > 0; value = Math.floor((value - 1) / 26)) name = String.fromCharCode(65 + ((value - 1) % 26)) + name; return name }
function safeSpreadsheetText(value: string) { return /^[=+\-@]/u.test(value) ? `'${value}` : value }
function xml(value: string) { return value.replace(/&/gu, '&amp;').replace(/</gu, '&lt;').replace(/>/gu, '&gt;').replace(/"/gu, '&quot;') }
function required<T>(value: T | null | undefined, code: string, message: string): T { if (value == null) throw new TestDesignError(code, message, code.endsWith('_NOT_FOUND') ? 404 : 409); return value }
function cleanRequired(value: unknown, label: string, max: number) { if (typeof value !== 'string' || !value.trim() || value.length > max) throw new TestDesignError('TEST_DESIGN_INPUT_INVALID', `${label} 不能为空且不能超过 ${max} 个字符`, 422); return value.trim() }
function positive(value: unknown, label: string) { const number = Number(value); if (!Number.isFinite(number) || number <= 0) throw new TestDesignError('TEST_DESIGN_INPUT_INVALID', `${label} 必须是正数`, 422); return number }
function newest(left: { createdAt?: string; publishedAt?: string }, right: { createdAt?: string; publishedAt?: string }) { return String(right.createdAt ?? right.publishedAt).localeCompare(String(left.createdAt ?? left.publishedAt)) }
function now() { return new Date().toISOString() }
function errorCode(message: string) { return /^([A-Z][A-Z0-9_]+):/u.exec(message)?.[1] ?? 'TEST_DESIGN_RUN_FAILED' }
